import { randomUUID } from "node:crypto";

/**
 * Prefixed UUID. Ported from the legacy MVP's `lib/ids.js` — the convention of
 * carrying the entity type in the id is worth keeping: it makes a stray id in a
 * log or an error message self-describing.
 *
 * Database primary keys are generated by Postgres (`gen_random_uuid()`), so
 * this is for identifiers we mint application-side: job ids, idempotency keys,
 * correlation ids.
 */
export function newId(prefix?: string): string {
  const uuid = randomUUID();
  return prefix ? `${prefix}_${uuid}` : uuid;
}

/**
 * Deterministic job id for BullMQ. Two enqueues of the same domain event
 * produce the same key, so a duplicate is a no-op rather than a second email.
 * Every `.add()` in the worker must pass one of these.
 */
export function jobKey(...parts: (string | number)[]): string {
  return parts.map((p) => String(p)).join(":");
}
